SourceCode.Declaration:
/// <summary>
/// The <c>AVADistributeRedemptionAmount</c> class
/// </summary>
class AVADistributeRedemptionAmount
{
    Args    clsArgs;

}

Method.Source:
/// <summary>
///    AVA <c>parmArgs</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>Args</c> as type
/// </param>
/// <returns>
///    <c>Args</c> as return value
/// </returns>
public Args parmArgs(Args _parmValue = clsArgs)
{
    clsArgs = _parmValue;

    return clsArgs;
}

/// <summary>
///    AVA <c>newFromArgs</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
/// <returns>
///    <c>AVADistributeRedemptionAmount</c> as return value
/// </returns>
public static AVADistributeRedemptionAmount newFromArgs(Args _args)
{
    AVADistributeRedemptionAmount   locAVADistributeRedemptionAmount;

    locAVADistributeRedemptionAmount = new AVADistributeRedemptionAmount();
    locAVADistributeRedemptionAmount.parmArgs(_args);

    return locAVADistributeRedemptionAmount;
}

/// <summary>
///    AVA <c>main</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
public static void main(Args _args)
{
    AVADistributeRedemptionAmount   locAVADistributeRedemptionAmount;

    if (!_args)
    {
        throw error("@SYS25407");
    }

    locAVADistributeRedemptionAmount  = AVADistributeRedemptionAmount::newFromArgs(_args);


    locAVADistributeRedemptionAmount.run();
}

/// <summary>
///    AVA <c>run</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean run()
{
    SalesTable  locSalesTable;
    Amount      locAmountToDistribute;

    Common      locCommon;
    boolean     locResult;

    Dialog      locDialog;
    DialogField locDialogField;

    if (clsArgs && clsArgs.record())
    {
        locCommon                           = clsArgs.record();
        if(locCommon.RecId && locCommon.TableId == tableNum(SalesTable))
        {
            locSalesTable                   = locCommon;

            locResult                       = locSalesTable.avaItemSetExpandedExist();
            if(locResult)
            {
                locResult                   = checkFailed("@NDX:NXADisributeRedemtionAmounNotPossible");
            }
            else
            {
                locDialog                   = new Dialog("@NDX:NXAEnterTotalAmountToBeDistributed");
                locDialogField              = locDialog.addFieldValue(  extendedTypeStr(Amount), 
                                                                        locAmountToDistribute, 
                                                                        "@SYS340849"            );
                if (locDialog.run())
                {
                    locAmountToDistribute   = locDialogField.value();
                }
                if(locAmountToDistribute)
                {
                    locResult               = locSalesTable.avaDistributeRedemptionAmount(locAmountToDistribute);
                }
            }
        }

    }
    return locResult;
}
